  // --- landing.features ---
  'landing.features.eyebrow': { fr: 'Fonctionnalités métier BTP', en: 'Core Construction Features', ar: 'وظائف البناء التخصصية' },
  'landing.features.heading': { fr: 'Tout pour remporter vos consultations publiques et privées', en: 'Everything to Win Your Public & Private Tenders', ar: 'كل ما تحتاجه للفوز بالمناقصات العامة والخاصة' },
  'landing.features.subtitle': { fr: 'Chaque module est spécialement entraîné sur les lexiques et normes du bâtiment.', en: 'Every module is purpose-trained on construction standards, regulations and engineering terms.', ar: 'كل وحدة مدربة خصيصاً على معايير البناء والمصطلحات الهندسية.' },
  
  'landing.features.f1_title': { fr: 'Extraction DCE & Pondération RC', en: 'RFP Extraction & Scoring Rules', ar: 'استخراج وثائق المناقصات وقواعد التقييم' },
  'landing.features.f1_desc': { fr: "Téléversez vos CCTP, RC, CCAP et BPU. L'IA extrait instantanément les exigences techniques, les critères de notation et les attentes clés de l'acheteur.", en: 'Upload tender specifications, evaluation criteria and bills of quantities. AI extracts mandatory technical requirements and key buyer expectations.', ar: 'ارفع المواصفات الفنية وشروط الاستشارة وجدول الأسعار. يستخرج الذكاء الاصطناعي الشروط الإلزامية ومعايير التقييم فوراً.' },

  'landing.features.f2_title': { fr: 'Qualification Go / No-Go Algorithmique', en: 'Algorithmic Go / No-Go Qualification', ar: 'تقييم الجدوى واتخاذ القرار Go / No-Go' },
  'landing.features.f2_desc': { fr: "Obtenez une note de faisabilité sur 100 basée sur votre savoir-faire passé, vos effectifs et vos contraintes de délais avant d'engager vos ressources.", en: 'Get a 0-100 feasibility score based on past projects, team capacities, and schedule deadlines before allocating estimating resources.', ar: 'احصل على درجة جدوى من 100 مبنية على سوابق خبراتك وفريق عملك ومواعيد التسليم قبل استثمار الموارد.' },

  'landing.features.f3_title': { fr: 'Planning Gantt & Organigramme IA', en: 'Interactive Gantt & Site Org Chart', ar: 'الجدول الزمني ومخطط الهيكل التنظيمي' },
  'landing.features.f3_desc': { fr: "Génération automatique du phasage de chantier avec chemin critique, durées en semaines et organigramme nominatif d'encadrement prêt à l'export.", en: 'Automatic generation of jobsite phasing with critical path, weekly task durations, and named supervision organigram ready for submission.', ar: 'إنشاء آلي لمراحل المشروع مع المسار الحرج والمُدد بالأسابيع والهيكل التنظيمي للمشرفين جاهز للتصدير.' },

  'landing.features.f4_title': { fr: 'Base de Savoir-faire & RAG Privé', en: 'Private Knowledge Base & Enterprise RAG', ar: 'قاعدة الخبرات والذكاء الاصطناعي الخاص' },
  'landing.features.f4_desc': { fr: "Indexation vectorielle de vos mémoires passés, fiches techniques, certifications Qualibat et CVs d'équipe pour une rédaction sur-mesure et certifiée.", en: 'Vector indexing of past winning proposals, technical data sheets, certifications and staff CVs for compliant, highly customized drafting.', ar: 'فهرسة دقيقة لمذكراتك الفنية السابقة وشهادات الاعتماد والسير الذاتية لصياغة دقيقة وموثوقة.' },

  'landing.features.f5_title': { fr: 'Export Word (.docx) & PDF Haute Fidélité', en: 'High-Fidelity Word (.docx) & PDF Export', ar: 'تصدير احترافي بصيغتي Word و PDF' },
  'landing.features.f5_desc': { fr: "Compilation instantanée de votre offre technique dans votre modèle Word officiel avec vos styles, en-têtes et logos d'entreprise.", en: 'Instant compilation of your technical offer into your official corporate Word template with custom headers, typography, and logos.', ar: 'تجميع فوري لعرضك الفني داخل قالب Word الرسمي لشركتك مع الخطوط والترويسة والشعار الخاص بكم.' },

  'landing.features.f6_title': { fr: 'Export International & Marchés MEA', en: 'International Export & MEA Markets', ar: 'التصدير الدولي وأسواق الشرق الأوسط' },
  'landing.features.f6_desc': { fr: 'Support des marchés internationaux (Arabie Saoudite, Qatar, EAU, Liban) avec export bilingue arabe/français/anglais et gestion de la mise en page RTL.', en: 'Support for international bids (Saudi Arabia, UAE, Qatar, Lebanon) with bilingual Arabic/French/English export and RTL typography layout.', ar: 'دعم المناقصات الدولية (السعودية، الإمارات، قطر، لبنان) مع التصدير متعدد اللغات وإدارة اتجاه النصوص من اليمين إلى اليسار.' },

