  // --- landing.faq ---
  'landing.faq.eyebrow': { fr: 'Questions fréquentes', en: 'Frequently Asked Questions', ar: 'الأسئلة الشائعة' },
  'landing.faq.heading': { fr: 'Tout ce que vous devez savoir', en: 'Everything You Need to Know', ar: 'كل ما تحتاج إلى معرفته' },
  'landing.faq.q1': { fr: "Mes données d'entreprise et mes mémoires techniques sont-ils confidentiels ?", en: 'Are my company data and technical proposals confidential?', ar: 'هل بيانات شركتنا ومذكراتنا الفنية محمية وسرية؟' },
  'landing.faq.a1': { fr: "Oui, à 100%. Vos documents de réponse, fiches techniques et savoir-faire sont strictement isolés dans votre espace entreprise privé. Ils ne sont jamais utilisés pour entraîner des modèles publics.", en: 'Yes, 100%. Your tender documents, technical data sheets, and corporate knowledge base are strictly isolated in your private workspace. They are never used to train public models.', ar: 'نعم بنسبة 100%. جميع مستندات العروض والبطاقات الفنية وقاعدة الخبرات معزولة بالكامل داخل مساحة شركتك الخاصة، ولا تُستخدم إطلاقاً لتدريب نماذج عامة.' },
  'landing.faq.q2': { fr: "Quels formats de DCE sont pris en charge ?", en: 'What tender file formats are supported?', ar: 'ما هي صيغ ملفات المناقصات المدعومة؟' },
  'landing.faq.a2': { fr: "La plateforme accepte les fichiers PDF, Word (.docx), Excel (.xlsx) et scans OCR jusqu'à 100 Mo par document.", en: 'The platform accepts PDF, Word (.docx), Excel (.xlsx), and scanned OCR files up to 100 MB per file.', ar: 'تدعم المنصة ملفات PDF و Word (.docx) و Excel (.xlsx) ومسح OCR الضوئي حتى 100 ميغابايت لكل ملف.' },
  'landing.faq.q3': { fr: "Puis-je intégrer le modèle Word (.docx) officiel de mon entreprise ?", en: "Can I upload our company's official Word (.docx) template?", ar: 'هل يمكنني إدراج قالب Word (.docx) الرسمي الخاص بشركتنا؟' },
  'landing.faq.a3': { fr: "Absolument. Dans la rubrique Modèles & Charte, vous pouvez téléverser votre propre fichier .docx avec vos en-têtes, polices et couleurs. Le générateur compilera directement votre mémoire dans votre matrice.", en: 'Absolutely. In the Templates & Branding section, you can upload your own .docx file with custom headers, typography, and color palette. The generator compiles your proposal directly into your matrix.', ar: 'بالتأكيد. في قسم النماذج والهوية، يمكنك رفع ملف .docx الخاص بشركتك مع الترويسة والخطوط والألوان، وسيقوم المحرك بتجميع العرض الفني داخل هذا القالب مباشرة.' },
  'landing.faq.q4': { fr: "Comment fonctionne l'essai gratuit de 14 jours ?", en: 'How does the 14-day free trial work?', ar: 'كيف تعمل الفترة التجريبية المجانية لمدة 14 يوماً؟' },
  'landing.faq.a4': { fr: "Vous bénéficiez d'un accès complet à l'ensemble des fonctionnalités de la plateforme dès la création de votre compte, sans obligation de paiement préalable.", en: 'You get full access to all platform features upon creating your account, with no upfront payment obligation.', ar: 'تحصل على وصول كامل وغير مقيد لكافة وظائف المنصة فور إنشاء حسابك، وبدون أي متطلبات دفع مسبقة.' },

