  'admin.super.keys.section_desc': { fr: 'Les clés sont chiffrées en AES-256-GCM avant d’être écrites en base : personne, y compris vous, ne les relit en clair depuis cet écran.', en: 'Keys are encrypted with AES-256-GCM before being written to the database: nobody, you included, reads them back in the clear from this screen.', ar: 'تُشفَّر المفاتيح بـ AES-256-GCM قبل حفظها في قاعدة البيانات.' },
