  'admin.super.keys.legend_title': { fr: 'Comment ces réglages se relient entre eux', en: 'How these settings connect', ar: 'كيف ترتبط هذه الإعدادات ببعضها' },
  'admin.super.keys.legend_body': { fr: "Un palier (ci-dessous) pointe vers un modèle chez un fournisseur (Anthropic, OpenAI, Mistral...). La clé API de ce fournisseur se configure plus bas, avec un plafond mensuel optionnel. La dépense réelle par fournisseur est suivie tout en bas de cette page.", en: "A tier (below) points to a model at a provider (Anthropic, OpenAI, Mistral...). That provider's API key is configured further down, with an optional monthly cap. Real spend per provider is tracked at the bottom of this page.", ar: "تشير الفئة (أدناه) إلى نموذج لدى مزوّد (Anthropic أو OpenAI أو Mistral...). يتم إعداد مفتاح API الخاص بهذا المزوّد أسفل الصفحة، مع سقف شهري اختياري. يتم تتبّع الإنفاق الفعلي لكل مزوّد أسفل هذه الصفحة." },
  'admin.super.keys.legend_link_keys': { fr: 'Voir les clés API des fournisseurs ↓', en: "See providers' API keys ↓", ar: 'عرض مفاتيح API للمزوّدين ↓' },
  'admin.super.keys.legend_link_usage': { fr: 'Voir la consommation & le budget ↓', en: 'See consumption & budget ↓', ar: 'عرض الاستهلاك والميزانية ↓' },
  'admin.super.keys.default_model_label': { fr: 'Modèle par défaut de la plateforme', en: 'Platform default model', ar: 'النموذج الافتراضي للمنصة' },
  'admin.super.keys.global_level_badge': { fr: 'Niveau Global Plateforme', en: 'Platform-wide Level', ar: 'مستوى عام للمنصة' },
  'admin.super.keys.default_model_desc': { fr: "C'est la valeur utilisée pour tout tenant qui n'a pas de réglage spécifique. Toi seul peux la changer, et le changement s'applique immédiatement à tous les tenants sans réglage individuel.", en: 'This is the value used for any tenant without a specific setting. Only you can change it, and the change applies immediately to all tenants without an individual override.', ar: 'هذه هي القيمة المستخدمة لأي مستأجر ليس له إعداد خاص. أنت وحدك من يمكنه تغييرها، ويُطبَّق التغيير فوراً على جميع المستأجرين الذين لا يملكون إعداداً فردياً.' },
  'admin.super.keys.configured_providers': { fr: 'Fournisseurs Configurés ({count})', en: 'Configured Providers ({count})', ar: 'المزوّدون المُهيّأون ({count})' },
  'admin.super.keys.providers_desc': { fr: 'Ajoutez, modifiez ou retirez un fournisseur. Tout point d’accès compatible OpenAI fonctionne.', en: 'Add, edit or remove a provider. Any OpenAI-compatible endpoint works.', ar: 'أضف أو عدّل أو احذف مزوّداً. أي نقطة وصول متوافقة مع OpenAI تعمل.' },
  'admin.super.keys.btn_add_provider': { fr: 'Ajouter un fournisseur', en: 'Add a provider', ar: 'إضافة مزوّد' },
  'admin.super.keys.tier_override_title': { fr: 'Substitution de modèle par palier (avancé)', en: 'Per-tier model override (advanced)', ar: 'استبدال النموذج حسب الفئة (متقدم)' },
  'admin.super.keys.tier_override_desc': { fr: "Pointez un palier vers n'importe quel modèle LiteLLM -- par exemple un modèle OpenRouter gratuit. Laissez vide pour garder le modèle par défaut du palier. Important : l'identifiant saisi ici doit correspondre EXACTEMENT à l'identifiant LiteLLM d'un fournisseur activé et doté d'une clé dans la liste ci-dessous, sinon aucune clé API ne sera trouvée pour l'appeler.", en: "Point a tier to any LiteLLM model -- for example a free OpenRouter model. Leave blank to keep the tier's default model. Important: the identifier entered here must match EXACTLY the LiteLLM identifier of an enabled provider with a key in the list below, otherwise no API key will be found to call it.", ar: 'وجّه فئة إلى أي نموذج LiteLLM -- مثلاً نموذج مجاني من OpenRouter. اتركه فارغاً للاحتفاظ بالنموذج الافتراضي للفئة. مهم: يجب أن يطابق المعرّف المدخل هنا تماماً معرّف LiteLLM لمزوّد مفعّل يملك مفتاحاً في القائمة أدناه، وإلا لن يتم العثور على أي مفتاح API لاستدعائه.' },
  'admin.super.keys.tier_override_current': { fr: 'Modèle actuellement actif', en: 'Currently active model', ar: 'النموذج النشط حالياً' },
  'admin.super.keys.tier_override_reset': { fr: 'Réinitialiser', en: 'Reset', ar: 'إعادة تعيين' },
  'admin.super.keys.label_monthly_budget': { fr: 'Plafond mensuel (USD, optionnel)', en: 'Monthly budget cap (USD, optional)', ar: 'السقف الشهري (دولار، اختياري)' },
  'admin.super.keys.placeholder_monthly_budget': { fr: 'Illimité', en: 'Unlimited', ar: 'غير محدود' },
  'admin.super.keys.usage_title': { fr: 'Consommation du mois', en: 'This month’s usage', ar: 'استهلاك الشهر' },
  'admin.super.keys.usage_desc': { fr: "Tokens et coût estimé par fournisseur depuis le 1er du mois, calculés à partir des vrais appels LLM. Le coût est une estimation basée sur le catalogue de prix ci-dessous -- vérifiez toujours la facture réelle du fournisseur.", en: "Tokens and estimated cost per provider since the 1st of the month, computed from real LLM calls. Cost is an estimate based on the pricing catalog below -- always check the provider's real invoice.", ar: 'الرموز والتكلفة التقديرية لكل مزوّد منذ بداية الشهر، محسوبة من طلبات LLM الحقيقية. التكلفة تقديرية استناداً إلى كتالوج الأسعار أدناه -- تحقق دائماً من الفاتورة الحقيقية للمزوّد.' },
